589	+/**
590	+ * Canonical JSON (object keys sorted, safe integers only), the same text `hashState` in `packages/simulation` hashes,
591	+ * so a moveset's version is also its state hash.
592	+ */
593	+function canonical(value: unknown): string {
594	+  if (value === null) return "null";
595	+  switch (typeof value) {
596	+    case "number":
597	+      if (!Number.isSafeInteger(value)) throw new TypeError(`move data numbers must be safe integers, got ${value}`);
598	+      return String(value);
599	+    case "string":
600	+      return JSON.stringify(value);
601	+    case "boolean":
602	+      return value ? "true" : "false";
603	+    case "object": {
604	+      if (Array.isArray(value)) return `[${value.map(canonical).join(",")}]`;
605	+      const entries = Object.keys(value)
606	+        .sort()
607	+        .filter((key) => (value as Record<string, unknown>)[key] !== undefined)
608	+        .map((key) => `${JSON.stringify(key)}:${canonical((value as Record<string, unknown>)[key])}`);
609	+      return `{${entries.join(",")}}`;
610	+    }
611	+    default:
612	+      throw new TypeError(`move data cannot hold a ${typeof value}`);
613	+  }
614	+}
