1	import { duelistMoveset, validateDuelInputLog } from "@pirate-sea-race/content/moves";
2	import { describe, expect, it } from "vitest";
3	import { canonicalize } from "../hash.js";
4	import { nextInt } from "../random.js";
5	import {
6	  createDuelInputLog,
7	  createDuelState,
8	  defaultDuelConfig as config,
9	  duelInput as I,
10	  hashState,
11	  mirrorDuelInput,
12	  MOVESET_VERSION,
13	  movesetVersion,
14	  replayDuel,
15	  restoreDuel,
16	  sliceDuelInputLog,
17	  snapshotDuel,
18	  stepDuel,
19	  traceDuel,
20	  type DuelConfig,
21	  type DuelEvent,
22	  type DuelInputs,
23	  type DuelState,
24	  type FighterState,
25	} from "./index.js";
26	
27	const FRAMES = config.moveset.rules.roundFrames;
28	
29	/** A seeded pseudo-random fight that lasts the round: mostly movement and guard, with occasional one-frame attacks. */
30	function randomInputs(seed: number, frames: number): DuelInputs[] {
31	  let rng = seed;
32	  const draw = (bound: number) => {
33	    const drawn = nextInt(rng, bound);
34	    rng = drawn.state;
35	    return drawn.value;
36	  };
37	  const held = [0, 0];
38	  const left = [0, 0];
39	  const inputs: DuelInputs[] = [];
40	  for (let frame = 0; frame < frames; frame++) {
41	    for (const player of [0, 1] as const) {
42	      if (left[player] === 0) {
43	        // Player one starts on the left, so its back is left; player two's is right.
44	        const back = player === 0 ? I("left") : I("right");
45	        const forward = player === 0 ? I("right") : I("left");
46	        const moves = [0, back, back, back | I("down"), forward, forward, I("down"), I("up"), I("up") | forward, I("up") | back, I("dash"), back | I("dash"), I("left", "right")];
47	        const attacks = [I("light"), I("heavy"), I("down", "heavy"), forward | I("heavy"), I("down", "light"), I("special1"), I("special2"), I("light", "heavy")];
48	        const attack = draw(100) < 12;
49	        held[player] = attack ? attacks[draw(attacks.length)]! : moves[draw(moves.length)]!;
50	        left[player] = attack ? 1 : 1 + draw(30);
51	      }
52	      left[player]!--;
53	    }
54	    inputs.push([held[0]!, held[1]!]);
55	  }
56	  return inputs;
57	}
58	
59	const INPUTS = randomInputs(2, FRAMES);
60	const LOG = createDuelInputLog(config, 0, INPUTS);
61	
62	describe("determinism (§19)", () => {
63	  it("gives the same hash for the same initial state and input log", () => {
64	    const first = replayDuel(config, createDuelState(config), LOG);
65	    const second = replayDuel(config, createDuelState(config), JSON.parse(JSON.stringify(LOG)));
66	    expect(second.hash).toBe(first.hash);
67	    expect(first.hash).toBe(hashState(first.state));
68	    // The fight runs the whole round to a timeout and exercises the rules, not just walking.
69	    expect(first.state.frame).toBe(FRAMES);
70	    expect(first.state.result).toMatchObject({ reason: "timeout", frame: FRAMES });
71	    const kinds = new Set(traceDuel(config, createDuelState(config), INPUTS).flatMap((state) => state.events.map((event) => event.kind)));
72	    expect([...kinds].sort()).toEqual(["block", "grab", "hit", "throw"]);
73	  });
74	
75	  it("gives a different hash when one input changes", () => {
